// Chart.js Simple Implementation
// Minimal implementation for basic charts

class Chart {
    constructor(ctx, config) {
        this.ctx = ctx.getContext ? ctx.getContext('2d') : ctx;
        this.canvas = ctx;
        this.config = config;
        this.draw();
    }

    draw() {
        const type = this.config.type;
        switch(type) {
            case 'doughnut':
                this.drawDoughnut();
                break;
            case 'bar':
                this.drawBar();
                break;
            case 'line':
                this.drawLine();
                break;
            default:
                this.drawDoughnut();
        }
    }

    drawDoughnut() {
        const data = this.config.data.datasets[0].data;
        const colors = this.config.data.datasets[0].backgroundColor;
        const labels = this.config.data.labels;

        const canvas = this.canvas;
        const ctx = this.ctx;
        const width = canvas.width || 400;
        const height = canvas.height || 300;

        const centerX = width / 2;
        const centerY = height / 2;
        const radius = Math.min(width, height) / 2 - 40;
        const innerRadius = radius * 0.6;

        let currentAngle = -Math.PI / 2;
        const total = data.reduce((a, b) => a + b, 0);

        // Draw doughnut slices
        data.forEach((value, index) => {
            const sliceAngle = (value / total) * Math.PI * 2;

            ctx.fillStyle = colors[index];
            ctx.beginPath();
            ctx.arc(centerX, centerY, radius, currentAngle, currentAngle + sliceAngle);
            ctx.lineTo(centerX + innerRadius * Math.cos(currentAngle + sliceAngle),
                      centerY + innerRadius * Math.sin(currentAngle + sliceAngle));
            ctx.arc(centerX, centerY, innerRadius, currentAngle + sliceAngle, currentAngle, true);
            ctx.closePath();
            ctx.fill();

            currentAngle += sliceAngle;
        });

        // Draw legend
        ctx.fillStyle = 'rgba(15, 23, 42, 0.8)';
        ctx.font = '12px sans-serif';
        let legendY = height - 40;

        labels.forEach((label, index) => {
            ctx.fillStyle = colors[index];
            ctx.fillRect(10, legendY - 8, 12, 12);
            ctx.fillStyle = 'rgba(15, 23, 42, 0.8)';
            ctx.fillText(label + ': ' + data[index], 30, legendY);
            legendY += 20;
        });
    }

    drawBar() {
        const data = this.config.data.datasets[0].data;
        const colors = this.config.data.datasets[0].backgroundColor;
        const labels = this.config.data.labels;

        const canvas = this.canvas;
        const ctx = this.ctx;
        const width = canvas.width || 400;
        const height = canvas.height || 300;

        const margin = 40;
        const chartWidth = width - margin * 2;
        const chartHeight = height - margin * 2;

        const max = Math.max(...data);
        const barHeight = chartHeight / labels.length;

        ctx.fillStyle = 'rgba(15, 23, 42, 0.2)';
        ctx.fillRect(margin, margin, chartWidth, chartHeight);

        labels.forEach((label, index) => {
            const y = margin + index * barHeight + barHeight / 2 - 15;
            const barWidth = (data[index] / max) * (chartWidth - 80);

            ctx.fillStyle = colors[index];
            ctx.fillRect(margin + 60, y + 5, barWidth, 30);

            ctx.fillStyle = 'rgba(15, 23, 42, 0.8)';
            ctx.font = '12px sans-serif';
            ctx.fillText(label, margin + 10, y + 25);
            ctx.fillText(data[index], margin + 60 + barWidth + 10, y + 25);
        });
    }

    drawLine() {
        // Simple line chart implementation
        const data = this.config.data.datasets[0].data;
        const color = this.config.data.datasets[0].backgroundColor || '#2563eb';
        const labels = this.config.data.labels;

        const canvas = this.canvas;
        const ctx = this.ctx;
        const width = canvas.width || 400;
        const height = canvas.height || 300;

        const margin = 40;
        const chartWidth = width - margin * 2;
        const chartHeight = height - margin * 2;

        const max = Math.max(...data);
        const min = Math.min(...data);
        const range = max - min || 1;

        // Draw grid
        ctx.strokeStyle = 'rgba(226, 232, 240, 0.5)';
        ctx.lineWidth = 1;
        for (let i = 0; i <= 5; i++) {
            const y = margin + (chartHeight / 5) * i;
            ctx.beginPath();
            ctx.moveTo(margin, y);
            ctx.lineTo(margin + chartWidth, y);
            ctx.stroke();
        }

        // Draw line
        ctx.strokeStyle = color;
        ctx.lineWidth = 2;
        ctx.beginPath();

        data.forEach((value, index) => {
            const x = margin + (chartWidth / (data.length - 1 || 1)) * index;
            const y = margin + chartHeight - ((value - min) / range) * chartHeight;

            if (index === 0) {
                ctx.moveTo(x, y);
            } else {
                ctx.lineTo(x, y);
            }
        });

        ctx.stroke();

        // Draw points
        ctx.fillStyle = color;
        data.forEach((value, index) => {
            const x = margin + (chartWidth / (data.length - 1 || 1)) * index;
            const y = margin + chartHeight - ((value - min) / range) * chartHeight;
            ctx.beginPath();
            ctx.arc(x, y, 4, 0, Math.PI * 2);
            ctx.fill();
        });
    }
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = Chart;
}
